// Content with portions generated by generative AI platform
package org.eclipse.kura.openapi;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Field;
import java.lang.reflect.GenericArrayType;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayDeque;
import java.util.Collection;
import java.util.Deque;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import org.junit.Test;
import org.yaml.snakeyaml.Yaml;

import com.fasterxml.jackson.databind.JsonNode;

import io.swagger.v3.core.util.Json;
import io.swagger.v3.oas.annotations.media.Schema;

public class SchemaNameUniquenessTest {

    private JsonNode document;
    private final Set<Class<?>> resources = new LinkedHashSet<>();
    private final Map<String, Set<Class<?>>> classesBySchemaName = new LinkedHashMap<>();

    @Test
    public void distinctClassesDoNotShareSchemaNames() throws Exception {
        givenGeneratedDocument();
        givenResourceClasses();

        whenModelClassesAreCollected();

        thenEachSchemaNameIsUsedByASingleClass();
        thenEveryModelClassIsDocumented();
    }

    private void givenGeneratedDocument() throws Exception {
        this.document = Json.mapper().readTree(Files.readString(
                Path.of(System.getProperty("openapi.directory"), "openapi.json")));
    }

    @SuppressWarnings("unchecked")
    private void givenResourceClasses() throws Exception {
        try (InputStream config = getClass().getResourceAsStream("/swagger-config.yaml")) {
            final Map<String, Object> loaded = new Yaml().load(config);
            for (final String className : (List<String>) loaded.get("resourceClasses")) {
                this.resources.add(Class.forName(className));
            }
        }
        assertFalse(this.resources.isEmpty());
    }

    private void whenModelClassesAreCollected() {
        final Deque<Class<?>> pending = new ArrayDeque<>(this.resources);
        final Set<Class<?>> visited = new HashSet<>();
        while (!pending.isEmpty()) {
            final Class<?> clazz = pending.poll();
            if (!visited.add(clazz)) {
                continue;
            }
            if (this.resources.contains(clazz)) {
                collectAnnotationReferences(clazz, pending);
            } else if (isModelClass(clazz)) {
                registerModelClass(clazz);
                collectFieldReferences(clazz, pending);
            }
        }
    }

    private void collectAnnotationReferences(final Class<?> clazz, final Deque<Class<?>> pending) {
        for (final Method method : clazz.getMethods()) {
            for (final Annotation annotation : method.getAnnotations()) {
                collectAnnotationReferences(annotation, pending);
            }
        }
    }

    private void collectAnnotationReferences(final Annotation annotation, final Deque<Class<?>> pending) {
        for (final Method member : annotation.annotationType().getDeclaredMethods()) {
            final Class<?> type = member.getReturnType();
            if (Class.class.equals(type)) {
                final Class<?> referenced = (Class<?>) invoke(member, annotation);
                if (!Void.class.equals(referenced)) {
                    pending.add(referenced);
                }
            } else if (Class[].class.equals(type)) {
                for (final Class<?> referenced : (Class<?>[]) invoke(member, annotation)) {
                    if (!Void.class.equals(referenced)) {
                        pending.add(referenced);
                    }
                }
            } else if (type.isArray() && Annotation.class.isAssignableFrom(type.getComponentType())) {
                for (final Annotation nested : (Annotation[]) invoke(member, annotation)) {
                    collectAnnotationReferences(nested, pending);
                }
            } else if (Annotation.class.isAssignableFrom(type)) {
                collectAnnotationReferences((Annotation) invoke(member, annotation), pending);
            }
        }
    }

    private void collectFieldReferences(final Class<?> clazz, final Deque<Class<?>> pending) {
        for (final Field field : clazz.getDeclaredFields()) {
            for (final Annotation annotation : field.getAnnotations()) {
                collectAnnotationReferences(annotation, pending);
            }
            collectFieldType(field.getGenericType(), pending);
        }
    }

    private void collectFieldType(final Type type, final Deque<Class<?>> pending) {
        if (type instanceof Class<?> clazz) {
            pending.add(clazz);
        } else if (type instanceof ParameterizedType parameterized) {
            final Class<?> raw = (Class<?>) parameterized.getRawType();
            if (Collection.class.isAssignableFrom(raw) || Map.class.isAssignableFrom(raw)) {
                for (final Type argument : parameterized.getActualTypeArguments()) {
                    collectFieldType(argument, pending);
                }
            } else {
                pending.add(raw);
            }
        } else if (type instanceof GenericArrayType array) {
            collectFieldType(array.getGenericComponentType(), pending);
        }
    }

    private boolean isModelClass(final Class<?> clazz) {
        return clazz.getName().startsWith("org.eclipse.kura") && !clazz.isEnum() && !clazz.isInterface()
                && !clazz.isAnnotation();
    }

    private void registerModelClass(final Class<?> clazz) {
        final Schema schema = clazz.getAnnotation(Schema.class);
        final String name = schema != null && !schema.name().isBlank() ? schema.name() : clazz.getSimpleName();
        this.classesBySchemaName.computeIfAbsent(name, key -> new LinkedHashSet<>()).add(clazz);
    }

    private void thenEachSchemaNameIsUsedByASingleClass() {
        for (final Map.Entry<String, Set<Class<?>>> entry : this.classesBySchemaName.entrySet()) {
            assertEquals("Schema name shared by multiple classes: " + entry.getKey(), 1, entry.getValue().size());
        }
        assertFalse(this.classesBySchemaName.isEmpty());
    }

    private void thenEveryModelClassIsDocumented() {
        for (final Map.Entry<String, Set<Class<?>>> entry : this.classesBySchemaName.entrySet()) {
            assertFalse("Missing generated schema: " + entry.getKey(),
                    this.document.path("components").path("schemas").path(entry.getKey()).isMissingNode());
        }
    }

    private Object invoke(final Method member, final Annotation annotation) {
        try {
            return member.invoke(annotation);
        } catch (IllegalAccessException | InvocationTargetException exception) {
            throw new IllegalStateException(exception);
        }
    }
}
